create domain public."bıgınt" as bigint;
create type public.mpaa_rating as enum ('G', 'PG', 'PG-13', 'R', 'NC-17');
create domain public.year as integer constraint year_check check (value >= 1901 and value <= 2155);
create function public._group_concat(text, text) returns text language sql immutable as $$ select case when $2 is null then $1 when $1 is null then $2 else $1 || ', ' || $2 end $$;
create aggregate public.group_concat(text) (sfunc = public._group_concat, stype = text);
create function public.last_updated() returns trigger language plpgsql as $$ begin new.last_update = current_timestamp; return new; end $$;
create table public.customer (customer_id serial primary key, first_name text not null, email text, active boolean default true not null, last_update timestamptz default now() not null, big public."bıgınt");
create table public.film (film_id serial primary key, title text not null, description text, release_year public.year, rating public.mpaa_rating default 'G', special_features text[], fulltext tsvector not null, last_update timestamptz default now() not null);
create index film_fulltext_idx on public.film using gist (fulltext);
create index idx_title on public.film (title);
create trigger film_fulltext_trigger before insert or update on public.film for each row execute function tsvector_update_trigger('fulltext', 'pg_catalog.english', 'title', 'description');
create trigger last_updated before update on public.film for each row execute function public.last_updated();
create function public.film_in_stock(p_film_id integer, p_store_id integer, out p_film_count integer) returns setof integer language sql as $$ select p_film_id $$;
create table public.payment (payment_id serial, customer_id integer not null references public.customer(customer_id), amount numeric(5,2) not null, payment_date timestamptz not null, primary key (payment_date, payment_id)) partition by range (payment_date);
create table public.payment_p2022_01 partition of public.payment for values from ('2022-01-01 00:00:00+00') to ('2022-02-01 00:00:00+00');
create table public.payment_p2022_04 partition of public.payment for values from ('2022-04-01 01:00:00+01') to ('2022-05-01 01:00:00+01');
create index idx_fk_customer on public.payment (customer_id);
create view public.customer_list as select c.customer_id as id, c.first_name || ' ' || coalesce(c.email, '') as name from public.customer c;
create materialized view public.film_titles as select film_id, title from public.film with no data;
create unique index film_titles_id on public.film_titles (film_id);
comment on domain public."bıgınt" is 'unicode name';
